224|/* For probing (after a collision) we need a step size relative prime
225|   to the hash table size, which is a power of 2. We use double-hashing,
226|   since we can calculate a second hash value cheaply by taking those bits
227|   of the first hash value that were discarded (masked out) when the table
228|   index was calculated: index = hash & mask, where mask = table->size - 1.
229|   We limit the maximum step size to table->size / 4 (mask >> 2) and make
230|   it odd, since odd numbers are always relative prime to a power of 2.
231|*/
232|#define SECOND_HASH(hash, mask, power)                                         \
233|  ((((hash) & ~(mask)) >> ((power) - 1)) & ((mask) >> 2))
234|#define PROBE_STEP(hash, mask, power)                                          \
235|  ((unsigned char)((SECOND_HASH(hash, mask, power)) | 1))
