797|static bool
798|expat_heap_increase_tolerable(XML_Parser rootParser, XmlBigCount increase,
799|                              int sourceLine) {
800|  assert(rootParser != NULL);
801|  assert(increase > 0);
802|
803|  XmlBigCount newTotal = 0;
804|  bool tolerable = true;
805|
806|  // Detect integer overflow
807|  if ((XmlBigCount)-1 - rootParser->m_alloc_tracker.bytesAllocated < increase) {
808|    tolerable = false;
809|  } else {
810|    newTotal = rootParser->m_alloc_tracker.bytesAllocated + increase;
811|
812|    if (newTotal >= rootParser->m_alloc_tracker.activationThresholdBytes) {
813|      assert(newTotal > 0);
814|      // NOTE: This can be +infinity when dividing by zero but not -nan
815|      const float amplification
816|          = (float)newTotal / (float)rootParser->m_accounting.countBytesDirect;
817|      if (amplification
818|          > rootParser->m_alloc_tracker.maximumAmplificationFactor) {
819|        tolerable = false;
820|      }
821|    }
822|  }
823|
824|  if (! tolerable && (rootParser->m_alloc_tracker.debugLevel >= 1)) {
825|    expat_heap_stat(rootParser, '+', increase, newTotal, newTotal, sourceLine);
826|  }
827|
828|  return tolerable;
