859|
860|  if (mallocedPtr == NULL) {
861|    return NULL;
862|  }
863|
864|  // Update in-block recorded size
865|  *(size_t *)mallocedPtr = size;
866|
867|  // Update accounting
868|  rootParser->m_alloc_tracker.bytesAllocated += bytesToAllocate;
869|
870|  // Report as needed
871|  if (rootParser->m_alloc_tracker.debugLevel >= 2) {
872|    if (rootParser->m_alloc_tracker.bytesAllocated
873|        > rootParser->m_alloc_tracker.peakBytesAllocated) {
