926|expat_realloc(XML_Parser parser, void *ptr, size_t size, int sourceLine) {
927|  assert(parser != NULL);
928|
929|  if (ptr == NULL) {
930|    return expat_malloc(parser, size, sourceLine);
931|  }
932|
933|  if (size == 0) {
934|    expat_free(parser, ptr, sourceLine);
935|    return NULL;
936|  }
937|
938|  const XML_Parser rootParser = getRootParserOf(parser, NULL);
939|  assert(rootParser->m_parentParser == NULL);
940|
941|  // Extract original size (to the eyes of the caller) and the original
942|  // pointer returned by malloc/realloc
943|  void *mallocedPtr = (char *)ptr - EXPAT_MALLOC_PADDING - sizeof(size_t);
944|  const size_t prevSize = *(size_t *)mallocedPtr;
945|
946|  // Classify upcoming change
947|  const bool isIncrease = (size > prevSize);
948|  const size_t absDiff
949|      = (size > prevSize) ? (size - prevSize) : (prevSize - size);
950|
951|  // Ask for permission from accounting
952|  if (isIncrease) {
953|    if (! expat_heap_increase_tolerable(rootParser, absDiff, sourceLine)) {
954|      return NULL; // i.e. signal violation as out-of-memory
955|    }
956|  }
957|
958|  // NOTE: Integer overflow detection has already been done for us
959|  //       by expat_heap_increase_tolerable(..) above
960|  assert(SIZE_MAX - sizeof(size_t) - EXPAT_MALLOC_PADDING >= size);
961|
962|  // Actually allocate
963|  mallocedPtr = parser->m_mem.realloc_fcn(
964|      mallocedPtr, sizeof(size_t) + EXPAT_MALLOC_PADDING + size);
965|
966|  if (mallocedPtr == NULL) {
967|    return NULL;
968|  }
969|
970|  // Update accounting
971|  if (isIncrease) {
972|    assert((XmlBigCount)-1 - rootParser->m_alloc_tracker.bytesAllocated
973|           >= absDiff);
974|    rootParser->m_alloc_tracker.bytesAllocated += absDiff;
975|  } else { // i.e. decrease
976|    assert(rootParser->m_alloc_tracker.bytesAllocated >= absDiff);
977|    rootParser->m_alloc_tracker.bytesAllocated -= absDiff;
978|  }
979|
980|  // Report as needed
981|  if (rootParser->m_alloc_tracker.debugLevel >= 2) {
982|    if (rootParser->m_alloc_tracker.bytesAllocated
983|        > rootParser->m_alloc_tracker.peakBytesAllocated) {
984|      rootParser->m_alloc_tracker.peakBytesAllocated
985|          = rootParser->m_alloc_tracker.bytesAllocated;
986|    }
987|    expat_heap_stat(rootParser, isIncrease ? '+' : '-', absDiff,
988|                    rootParser->m_alloc_tracker.bytesAllocated,
989|                    rootParser->m_alloc_tracker.peakBytesAllocated, sourceLine);
990|  }
991|
992|  // Update in-block recorded size
993|  *(size_t *)mallocedPtr = size;
994|
995|  return (char *)mallocedPtr + sizeof(size_t) + EXPAT_MALLOC_PADDING;
