1080|static unsigned long
1081|generate_hash_secret_salt(XML_Parser parser) {
1082|  unsigned long entropy;
1083|  (void)parser;
1084|
1085|  /* "Failproof" high quality providers: */
1086|#if defined(HAVE_ARC4RANDOM_BUF)
1087|  arc4random_buf(&entropy, sizeof(entropy));
1088|  return ENTROPY_DEBUG("arc4random_buf", entropy);
1089|#elif defined(HAVE_ARC4RANDOM)
1090|  writeRandomBytes_arc4random((void *)&entropy, sizeof(entropy));
1091|  return ENTROPY_DEBUG("arc4random", entropy);
1092|#else
1093|  /* Try high quality providers first .. */
1094|#  ifdef _WIN32
1095|  if (writeRandomBytes_rand_s((void *)&entropy, sizeof(entropy))) {
1096|    return ENTROPY_DEBUG("rand_s", entropy);
1097|  }
1098|#  elif defined(HAVE_GETENTROPY)
1099|  if (writeRandomBytes_getentropy(&entropy, sizeof(entropy))) {
1100|    return ENTROPY_DEBUG("getentropy", entropy);
1101|  }
1102|  errno = 0;
1103|#  elif defined(HAVE_GETRANDOM) || defined(HAVE_SYSCALL_GETRANDOM)
1104|  if (writeRandomBytes_getrandom_nonblock((void *)&entropy, sizeof(entropy))) {
1105|    return ENTROPY_DEBUG("getrandom", entropy);
1106|  }
1107|#  endif
1108|#  if ! defined(_WIN32) && defined(XML_DEV_URANDOM)
1109|  if (writeRandomBytes_dev_urandom((void *)&entropy, sizeof(entropy))) {
1110|    return ENTROPY_DEBUG("/dev/urandom", entropy);
1111|  }
1112|#  endif /* ! defined(_WIN32) && defined(XML_DEV_URANDOM) */
1113|  /* .. and self-made low quality for backup: */
1114|
1115|  entropy = gather_time_entropy();
1116|#  if ! defined(__wasi__)
1117|  /* Process ID is 0 bits entropy if attacker has local access */
1118|  entropy ^= getpid();
1119|#  endif
1120|
1121|  /* Factors are 2^31-1 and 2^61-1 (Mersenne primes M31 and M61) */
1122|  if (sizeof(unsigned long) == 4) {
1123|    return ENTROPY_DEBUG("fallback(4)", entropy * 2147483647);
1124|  } else {
1125|    return ENTROPY_DEBUG("fallback(8)",
1126|                         entropy * (unsigned long)2305843009213693951ULL);
1127|  }
1128|#endif
1129|}
