1139|static enum XML_Error
1140|callProcessor(XML_Parser parser, const char *start, const char *end,
1141|              const char **endPtr) {
1142|  const size_t have_now = EXPAT_SAFE_PTR_DIFF(end, start);
1143|
1144|  if (parser->m_reparseDeferralEnabled
1145|      && ! parser->m_parsingStatus.finalBuffer) {
1146|    // Heuristic: don't try to parse a partial token again until the amount of
1147|    // available data has increased significantly.
1148|    const size_t had_before = parser->m_partialTokenBytesBefore;
1149|    // ...but *do* try anyway if we're close to causing a reallocation.
1150|    size_t available_buffer
1151|        = EXPAT_SAFE_PTR_DIFF(parser->m_bufferPtr, parser->m_buffer);
1152|#if XML_CONTEXT_BYTES > 0
1153|    available_buffer -= EXPAT_MIN(available_buffer, XML_CONTEXT_BYTES);
1154|#endif
1155|    available_buffer
1156|        += EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_bufferEnd);
1157|    // m_lastBufferRequestSize is never assigned a value < 0, so the cast is ok
1158|    const bool enough
1159|        = (have_now >= 2 * had_before)
1160|          || ((size_t)parser->m_lastBufferRequestSize > available_buffer);
1161|
1162|    if (! enough) {
1163|      *endPtr = start; // callers may expect this to be set
1164|      return XML_ERROR_NONE;
1165|    }
1166|  }
1167|#if defined(XML_TESTING)
1168|  g_bytesScanned += (unsigned)have_now;
1169|#endif
1170|  // Run in a loop to eliminate dangerous recursion depths
1171|  enum XML_Error ret;
1172|  *endPtr = start;
1173|  while (1) {
1174|    // Use endPtr as the new start in each iteration, since it will
1175|    // be set to the next start point by m_processor.
1176|    ret = parser->m_processor(parser, *endPtr, end, endPtr);
1177|
1178|    // Make parsing status (and in particular XML_SUSPENDED) take
1179|    // precedence over re-enter flag when they disagree
1180|    if (parser->m_parsingStatus.parsing != XML_PARSING) {
1181|      parser->m_reenter = XML_FALSE;
1182|    }
1183|
1184|    if (! parser->m_reenter) {
1185|      break;
1186|    }
1187|
1188|    parser->m_reenter = XML_FALSE;
1189|    if (ret != XML_ERROR_NONE)
1190|      return ret;
1191|  }
1192|
1193|  if (ret == XML_ERROR_NONE) {
1194|    // if we consumed nothing, remember what we had on this parse attempt.
1195|    if (*endPtr == start) {
1196|      parser->m_partialTokenBytesBefore = have_now;
1197|    } else {
1198|      parser->m_partialTokenBytesBefore = 0;
1199|    }
1200|  }
1201|  return ret;
1202|}
