2545|XML_StopParser(XML_Parser parser, XML_Bool resumable) {
2546|  if (parser == NULL)
2547|    return XML_STATUS_ERROR;
2548|  switch (parser->m_parsingStatus.parsing) {
2549|  case XML_INITIALIZED:
2550|    parser->m_errorCode = XML_ERROR_NOT_STARTED;
2551|    return XML_STATUS_ERROR;
2552|  case XML_SUSPENDED:
2553|    if (resumable) {
2554|      parser->m_errorCode = XML_ERROR_SUSPENDED;
2555|      return XML_STATUS_ERROR;
2556|    }
2557|    parser->m_parsingStatus.parsing = XML_FINISHED;
2558|    break;
2559|  case XML_FINISHED:
2560|    parser->m_errorCode = XML_ERROR_FINISHED;
2561|    return XML_STATUS_ERROR;
2562|  case XML_PARSING:
2563|    if (resumable) {
2564|#ifdef XML_DTD
2565|      if (parser->m_isParamEntity) {
2566|        parser->m_errorCode = XML_ERROR_SUSPEND_PE;
2567|        return XML_STATUS_ERROR;
2568|      }
2569|#endif
2570|      parser->m_parsingStatus.parsing = XML_SUSPENDED;
2571|    } else
2572|      parser->m_parsingStatus.parsing = XML_FINISHED;
2573|    break;
2574|  default:
2575|    assert(0);
2576|  }
2577|  return XML_STATUS_OK;
