2580|enum XML_Status XMLCALL
2581|XML_ResumeParser(XML_Parser parser) {
2582|  enum XML_Status result = XML_STATUS_OK;
2583|
2584|  if (parser == NULL)
2585|    return XML_STATUS_ERROR;
2586|  if (parser->m_parsingStatus.parsing != XML_SUSPENDED) {
2587|    parser->m_errorCode = XML_ERROR_NOT_SUSPENDED;
2588|    return XML_STATUS_ERROR;
2589|  }
2590|  parser->m_parsingStatus.parsing = XML_PARSING;
2591|
2592|  parser->m_errorCode = callProcessor(
2593|      parser, parser->m_bufferPtr, parser->m_parseEndPtr, &parser->m_bufferPtr);
