2862|const XML_LChar *XMLCALL
2863|XML_ExpatVersion(void) {
2864|  /* V1 is used to string-ize the version number. However, it would
2865|     string-ize the actual version macro *names* unless we get them
2866|     substituted before being passed to V1. CPP is defined to expand
2867|     a macro, then rescan for more expansions. Thus, we use V2 to expand
2868|     the version macros, then CPP will expand the resulting V1() macro
2869|     with the correct numerals. */
2870|  /* ### I'm assuming cpp is portable in this respect... */
2871|
2872|#define V1(a, b, c) XML_L(#a) XML_L(".") XML_L(#b) XML_L(".") XML_L(#c)
2873|#define V2(a, b, c) XML_L("expat_") V1(a, b, c)
2874|
2875|  return V2(XML_MAJOR_VERSION, XML_MINOR_VERSION, XML_MICRO_VERSION);
2876|
2877|#undef V1
2878|#undef V2
2879|}
