4296|      = {ASCII_h,      ASCII_t,     ASCII_t,     ASCII_p,      ASCII_COLON,
4297|         ASCII_SLASH,  ASCII_SLASH, ASCII_w,     ASCII_w,      ASCII_w,
4298|         ASCII_PERIOD, ASCII_w,     ASCII_3,     ASCII_PERIOD, ASCII_o,
4299|         ASCII_r,      ASCII_g,     ASCII_SLASH, ASCII_X,      ASCII_M,
4300|         ASCII_L,      ASCII_SLASH, ASCII_1,     ASCII_9,      ASCII_9,
4301|         ASCII_8,      ASCII_SLASH, ASCII_n,     ASCII_a,      ASCII_m,
4302|         ASCII_e,      ASCII_s,     ASCII_p,     ASCII_a,      ASCII_c,
4303|         ASCII_e,      '\0'};
