4408|    b = MALLOC(parser, sizeof(BINDING));
4409|    if (! b)
4410|      return XML_ERROR_NO_MEMORY;
4411|
4412|    /* Detect and prevent integer overflow */
4413|    if (len > INT_MAX - EXPAND_SPARE) {
4414|      return XML_ERROR_NO_MEMORY;
4415|    }
4416|    /* Detect and prevent integer overflow.
4417|     * The preprocessor guard addresses the "always false" warning
4418|     * from -Wtype-limits on platforms where
4419|     * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
4420|#if UINT_MAX >= SIZE_MAX
4421|    if ((unsigned)(len + EXPAND_SPARE) > SIZE_MAX / sizeof(XML_Char)) {
