4501|#if XML_GE == 1
4502|    if (! accountingDiffTolerated(parser, tok, s, next, __LINE__, account)) {
4503|      accountingOnAbort(parser);
4504|      return XML_ERROR_AMPLIFICATION_LIMIT_BREACH;
