4540|            ICHAR *dataPtr = (ICHAR *)parser->m_dataBuf;
4541|            const enum XML_Convert_Result convert_res = XmlConvert(
4542|                enc, &s, next, &dataPtr, (ICHAR *)parser->m_dataBufEnd);
4543|            *eventEndPP = next;
4544|            charDataHandler(parser->m_handlerArg, parser->m_dataBuf,
4545|                            (int)(dataPtr - (ICHAR *)parser->m_dataBuf));
4546|            if ((convert_res == XML_CONVERT_COMPLETED)
4547|                || (convert_res == XML_CONVERT_INPUT_INCOMPLETE))
