4566|    case XML_TOK_PARTIAL:
4567|    case XML_TOK_NONE:
4568|      if (haveMore) {
4569|        *nextPtr = s;
4570|        return XML_ERROR_NONE;
4571|      }
4572|      return XML_ERROR_UNCLOSED_CDATA_SECTION;
4573|    default:
4574|      /* Every token returned by XmlCdataSectionTok() has its own
4575|       * explicit case, so this default case will never be executed.
4576|       * We retain it as a safety net and exclude it from the coverage
