7745|    size_t tsize;
7746|    if (! createSize)
7747|      return NULL;
7748|    table->power = INIT_POWER;
7749|    /* table->size is a power of 2 */
7750|    table->size = (size_t)1 << INIT_POWER;
7751|    tsize = table->size * sizeof(NAMED *);
7752|    table->v = MALLOC(table->parser, tsize);
7753|    if (! table->v) {
7754|      table->size = 0;
7755|      return NULL;
7756|    }
7757|    memset(table->v, 0, tsize);
7758|    i = hash(parser, name) & ((unsigned long)table->size - 1);
7759|  } else {
7760|    unsigned long h = hash(parser, name);
7761|    unsigned long mask = (unsigned long)table->size - 1;
7762|    unsigned char step = 0;
7763|    i = h & mask;
7764|    while (table->v[i]) {
7765|      if (keyeq(name, table->v[i]->name))
7766|        return table->v[i];
7767|      if (! step)
7768|        step = PROBE_STEP(h, mask, table->power);
7769|      i < step ? (i += table->size - step) : (i -= step);
7770|    }
7771|    if (! createSize)
7772|      return NULL;
7773|
7774|    /* check for overflow (table is half full) */
7775|    if (table->used >> (table->power - 1)) {
7776|      unsigned char newPower = table->power + 1;
7777|
7778|      /* Detect and prevent invalid shift */
7779|      if (newPower >= sizeof(unsigned long) * 8 /* bits per byte */) {
7780|        return NULL;
7781|      }
7782|
7783|      size_t newSize = (size_t)1 << newPower;
7784|      unsigned long newMask = (unsigned long)newSize - 1;
7785|
7786|      /* Detect and prevent integer overflow */
7787|      if (newSize > SIZE_MAX / sizeof(NAMED *)) {
7788|        return NULL;
7789|      }
7790|
7791|      size_t tsize = newSize * sizeof(NAMED *);
7792|      NAMED **newV = MALLOC(table->parser, tsize);
7793|      if (! newV)
7794|        return NULL;
7795|      memset(newV, 0, tsize);
7796|      for (i = 0; i < table->size; i++)
7797|        if (table->v[i]) {
7798|          unsigned long newHash = hash(parser, table->v[i]->name);
7799|          size_t j = newHash & newMask;
7800|          step = 0;
7801|          while (newV[j]) {
7802|            if (! step)
7803|              step = PROBE_STEP(newHash, newMask, newPower);
7804|            j < step ? (j += newSize - step) : (j -= step);
7805|          }
7806|          newV[j] = table->v[i];
7807|        }
7808|      FREE(table->parser, table->v);
7809|      table->v = newV;
7810|      table->power = newPower;
7811|      table->size = newSize;
7812|      i = h & newMask;
7813|      step = 0;
7814|      while (table->v[i]) {
7815|        if (! step)
7816|          step = PROBE_STEP(h, newMask, newPower);
7817|        i < step ? (i += newSize - step) : (i -= step);
7818|      }
7819|    }
