8009|static size_t
8010|poolBytesToAllocateFor(int blockSize) {
8011|  /* Unprotected math would be:
8012|  ** return offsetof(BLOCK, s) + blockSize * sizeof(XML_Char);
8013|  **
8014|  ** Detect overflow, avoiding _signed_ overflow undefined behavior
8015|  ** For a + b * c we check b * c in isolation first, so that addition of a
8016|  ** on top has no chance of making us accept a small non-negative number
8017|  */
8018|  const size_t stretch = sizeof(XML_Char); /* can be 4 bytes */
8019|
8020|  if (blockSize <= 0)
8021|    return 0;
8022|
8023|  if (blockSize > (int)(INT_MAX / stretch))
8024|    return 0;
8025|
8026|  {
8027|    const int stretchedBlockSize = blockSize * (int)stretch;
8028|    const int bytesToAllocate
8029|        = (int)(offsetof(BLOCK, s) + (unsigned)stretchedBlockSize);
8030|    if (bytesToAllocate < 0)
8031|      return 0;
8032|
8033|    return (size_t)bytesToAllocate;
8034|  }
