8037|static XML_Bool FASTCALL
8038|poolGrow(STRING_POOL *pool) {
8039|  if (pool->freeBlocks) {
8040|    if (pool->start == NULL) {
8041|      pool->blocks = pool->freeBlocks;
8042|      pool->freeBlocks = pool->freeBlocks->next;
8043|      pool->blocks->next = NULL;
8044|      pool->start = pool->blocks->s;
8045|      pool->end = pool->start + pool->blocks->size;
8046|      pool->ptr = pool->start;
8047|      return XML_TRUE;
8048|    }
8049|    if (pool->end - pool->start < pool->freeBlocks->size) {
8050|      BLOCK *tem = pool->freeBlocks->next;
8051|      pool->freeBlocks->next = pool->blocks;
8052|      pool->blocks = pool->freeBlocks;
8053|      pool->freeBlocks = tem;
8054|      memcpy(pool->blocks->s, pool->start,
8055|             (pool->end - pool->start) * sizeof(XML_Char));
8056|      pool->ptr = pool->blocks->s + (pool->ptr - pool->start);
8057|      pool->start = pool->blocks->s;
8058|      pool->end = pool->start + pool->blocks->size;
8059|      return XML_TRUE;
8060|    }
8061|  }
8062|  if (pool->blocks && pool->start == pool->blocks->s) {
8063|    BLOCK *temp;
8064|    int blockSize = (int)((unsigned)(pool->end - pool->start) * 2U);
8065|    size_t bytesToAllocate;
8066|
8067|    /* NOTE: Needs to be calculated prior to calling `realloc`
8068|             to avoid dangling pointers: */
8069|    const ptrdiff_t offsetInsideBlock = pool->ptr - pool->start;
8070|
8071|    if (blockSize < 0) {
8072|      /* This condition traps a situation where either more than
8073|       * INT_MAX/2 bytes have already been allocated.  This isn't
8074|       * readily testable, since it is unlikely that an average
8075|       * machine will have that much memory, so we exclude it from the
8076|       * coverage statistics.
8077|       */
8078|      return XML_FALSE; /* LCOV_EXCL_LINE */
8079|    }
8080|
8081|    bytesToAllocate = poolBytesToAllocateFor(blockSize);
8082|    if (bytesToAllocate == 0)
8083|      return XML_FALSE;
8084|
8085|    temp = REALLOC(pool->parser, pool->blocks, bytesToAllocate);
8086|    if (temp == NULL)
8087|      return XML_FALSE;
8088|    pool->blocks = temp;
8089|    pool->blocks->size = blockSize;
8090|    pool->ptr = pool->blocks->s + offsetInsideBlock;
8091|    pool->start = pool->blocks->s;
8092|    pool->end = pool->start + blockSize;
8093|  } else {
8094|    BLOCK *tem;
8095|    int blockSize = (int)(pool->end - pool->start);
8096|    size_t bytesToAllocate;
8097|
8098|    if (blockSize < 0) {
8099|      /* This condition traps a situation where either more than
8100|       * INT_MAX bytes have already been allocated (which is prevented
8101|       * by various pieces of program logic, not least this one, never
8102|       * mind the unlikelihood of actually having that much memory) or
8103|       * the pool control fields have been corrupted (which could
8104|       * conceivably happen in an extremely buggy user handler
8105|       * function).  Either way it isn't readily testable, so we
8106|       * exclude it from the coverage statistics.
8107|       */
8108|      return XML_FALSE; /* LCOV_EXCL_LINE */
8109|    }
8110|
8111|    if (blockSize < INIT_BLOCK_SIZE)
8112|      blockSize = INIT_BLOCK_SIZE;
8113|    else {
8114|      /* Detect overflow, avoiding _signed_ overflow undefined behavior */
8115|      if ((int)((unsigned)blockSize * 2U) < 0) {
8116|        return XML_FALSE;
8117|      }
8118|      blockSize *= 2;
8119|    }
8120|
8121|    bytesToAllocate = poolBytesToAllocateFor(blockSize);
8122|    if (bytesToAllocate == 0)
8123|      return XML_FALSE;
8124|
8125|    tem = MALLOC(pool->parser, bytesToAllocate);
8126|    if (! tem)
8127|      return XML_FALSE;
8128|    tem->size = blockSize;
8129|    tem->next = pool->blocks;
8130|    pool->blocks = tem;
8131|    if (pool->ptr != pool->start)
8132|      memcpy(tem->s, pool->start, (pool->ptr - pool->start) * sizeof(XML_Char));
8133|    pool->ptr = tem->s + (pool->ptr - pool->start);
8134|    pool->start = tem->s;
8135|    pool->end = tem->s + blockSize;
8136|  }
8137|  return XML_TRUE;
