8173|      }
8174|      /* Detect and prevent integer overflow.
8175|       * The preprocessor guard addresses the "always false" warning
8176|       * from -Wtype-limits on platforms where
8177|       * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
8178|#if UINT_MAX >= SIZE_MAX
8179|      if (dtd->scaffSize > SIZE_MAX / 2u / sizeof(CONTENT_SCAFFOLD)) {
8180|        return -1;
8181|      }
8182|#endif
8183|
8184|      temp = REALLOC(parser, dtd->scaffold,
