8214|static XML_Content *
8215|build_model(XML_Parser parser) {
8216|  /* Function build_model transforms the existing parser->m_dtd->scaffold
8217|   * array of CONTENT_SCAFFOLD tree nodes into a new array of
8218|   * XML_Content tree nodes followed by a gapless list of zero-terminated
8219|   * strings. */
8220|  DTD *const dtd = parser->m_dtd; /* save one level of indirection */
8221|  XML_Content *ret;
8222|  XML_Char *str; /* the current string writing location */
8223|
8224|  /* Detect and prevent integer overflow.
8225|   * The preprocessor guard addresses the "always false" warning
8226|   * from -Wtype-limits on platforms where
8227|   * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
8228|#if UINT_MAX >= SIZE_MAX
8229|  if (dtd->scaffCount > SIZE_MAX / sizeof(XML_Content)) {
8230|    return NULL;
8231|  }
8232|  if (dtd->contentStringLen > SIZE_MAX / sizeof(XML_Char)) {
8233|    return NULL;
8234|  }
8235|#endif
8236|  if (dtd->scaffCount * sizeof(XML_Content)
8237|      > SIZE_MAX - dtd->contentStringLen * sizeof(XML_Char)) {
8238|    return NULL;
8239|  }
8240|
8241|  const size_t allocsize = (dtd->scaffCount * sizeof(XML_Content)
8242|                            + (dtd->contentStringLen * sizeof(XML_Char)));
8243|
8244|  // NOTE: We are avoiding MALLOC(..) here to so that
8245|  //       applications that are not using XML_FreeContentModel but plain
8246|  //       free(..) or .free_fcn() to free the content model's memory are safe.
8247|  ret = parser->m_mem.malloc_fcn(allocsize);
8248|  if (! ret)
8249|    return NULL;
8250|
8251|  /* What follows is an iterative implementation (of what was previously done
8252|   * recursively in a dedicated function called "build_node".  The old recursive
8253|   * build_node could be forced into stack exhaustion from input as small as a
8254|   * few megabyte, and so that was a security issue.  Hence, a function call
8255|   * stack is avoided now by resolving recursion.)
8256|   *
8257|   * The iterative approach works as follows:
8258|   *
8259|   * - We have two writing pointers, both walking up the result array; one does
8260|   *   the work, the other creates "jobs" for its colleague to do, and leads
8261|   *   the way:
8262|   *
8263|   *   - The faster one, pointer jobDest, always leads and writes "what job
8264|   *     to do" by the other, once they reach that place in the
8265|   *     array: leader "jobDest" stores the source node array index (relative
8266|   *     to array dtd->scaffold) in field "numchildren".
8267|   *
8268|   *   - The slower one, pointer dest, looks at the value stored in the
8269|   *     "numchildren" field (which actually holds a source node array index
8270|   *     at that time) and puts the real data from dtd->scaffold in.
8271|   *
8272|   * - Before the loop starts, jobDest writes source array index 0
8273|   *   (where the root node is located) so that dest will have something to do
8274|   *   when it starts operation.
8275|   *
8276|   * - Whenever nodes with children are encountered, jobDest appends
8277|   *   them as new jobs, in order.  As a result, tree node siblings are
8278|   *   adjacent in the resulting array, for example:
8279|   *
8280|   *     [0] root, has two children
8281|   *       [1] first child of 0, has three children
8282|   *         [3] first child of 1, does not have children
8283|   *         [4] second child of 1, does not have children
8284|   *         [5] third child of 1, does not have children
8285|   *       [2] second child of 0, does not have children
8286|   *
8287|   *   Or (the same data) presented in flat array view:
8288|   *
8289|   *     [0] root, has two children
8290|   *
8291|   *     [1] first child of 0, has three children
8292|   *     [2] second child of 0, does not have children
8293|   *
8294|   *     [3] first child of 1, does not have children
8295|   *     [4] second child of 1, does not have children
8296|   *     [5] third child of 1, does not have children
8297|   *
8298|   * - The algorithm repeats until all target array indices have been processed.
8299|   */
8300|  XML_Content *dest = ret; /* tree node writing location, moves upwards */
8301|  XML_Content *const destLimit = &ret[dtd->scaffCount];
8302|  XML_Content *jobDest = ret; /* next free writing location in target array */
8303|  str = (XML_Char *)&ret[dtd->scaffCount];
8304|
8305|  /* Add the starting job, the root node (index 0) of the source tree  */
8306|  (jobDest++)->numchildren = 0;
8307|
8308|  for (; dest < destLimit; dest++) {
8309|    /* Retrieve source tree array index from job storage */
8310|    const int src_node = (int)dest->numchildren;
8311|
8312|    /* Convert item */
8313|    dest->type = dtd->scaffold[src_node].type;
8314|    dest->quant = dtd->scaffold[src_node].quant;
8315|    if (dest->type == XML_CTYPE_NAME) {
8316|      const XML_Char *src;
8317|      dest->name = str;
8318|      src = dtd->scaffold[src_node].name;
8319|      for (;;) {
8320|        *str++ = *src;
8321|        if (! *src)
8322|          break;
8323|        src++;
8324|      }
8325|      dest->numchildren = 0;
8326|      dest->children = NULL;
8327|    } else {
8328|      unsigned int i;
8329|      int cn;
8330|      dest->name = NULL;
8331|      dest->numchildren = dtd->scaffold[src_node].childcnt;
8332|      dest->children = jobDest;
8333|
8334|      /* Append scaffold indices of children to array */
8335|      for (i = 0, cn = dtd->scaffold[src_node].firstchild;
8336|           i < dest->numchildren; i++, cn = dtd->scaffold[cn].nextsib)
8337|        (jobDest++)->numchildren = (unsigned int)cn;
8338|    }
8339|  }
8340|
8341|  return ret;
8342|}
